#!/usr/bin/env python3
"""Compare what NEW tokens each run added to the main session context.

cache_creation_input_tokens on an assistant turn = tokens *newly* added
to the KV cache that turn. Sum across turns = total new material the
main session ingested. Subagent tool_result messages return the
subagent's final text, and only that text counts against the main
session's cache_creation. Reading a file directly in the main session
adds ALL of that file's tokens to cache_creation.
"""
import json, sys, os

def analyze(path):
    total_create = 0
    total_output = 0
    policy_reads = 0
    subagent_calls = 0
    subagent_return_tokens = 0
    turns = 0
    for line in open(path):
        if not line.strip():
            continue
        try:
            j = json.loads(line)
        except Exception:
            continue
        t = j.get("type")
        if t == "assistant":
            m = j.get("message", {})
            u = m.get("usage", {}) or {}
            total_create += u.get("cache_creation_input_tokens", 0)
            total_output += u.get("output_tokens", 0)
            turns += 1
            for c in m.get("content", []):
                if c.get("type") == "tool_use":
                    name = c.get("name")
                    args = c.get("input", {}) or {}
                    if name == "Read":
                        fp = args.get("file_path", "")
                        if "policies/" in fp or "\\policies\\" in fp:
                            policy_reads += 1
                    if name == "Task":
                        subagent_calls += 1
        if t == "user":
            m = j.get("message", {})
            for c in m.get("content", []) if isinstance(m.get("content"), list) else []:
                if c.get("type") == "tool_result":
                    tc = c.get("content", "")
                    if isinstance(tc, list):
                        for x in tc:
                            if x.get("type") == "text":
                                tc = x.get("text", "")
                                break
                    if isinstance(tc, str) and (
                        "study group" in tc.lower()
                        or "late-submission" in tc.lower()
                        or "late submission" in tc.lower()
                        or "grace hour" in tc.lower()
                    ) and len(tc) > 200:
                        subagent_return_tokens = max(subagent_return_tokens, len(tc.split())*4//3)
    print(f"{os.path.basename(path)}:")
    print(f"  assistant turns: {turns}")
    print(f"  TOTAL cache_creation (new tokens INTO main context): {total_create}")
    print(f"  output tokens (assistant thinking/action): {total_output}")
    print(f"  main-session Reads of policies/*.md: {policy_reads}")
    print(f"  Task (subagent) calls: {subagent_calls}")
    print(f"  approx tokens in subagent's return summary: {subagent_return_tokens}")

for p in sys.argv[1:]:
    analyze(p)
    print()

